{"code":"import pandas as pd, statsmodels.api as sm
D=pd.read_csv('data/explore.csv'); xs=['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
for x in xs:
 d=D.dropna(subset=[x,'yield_kg']); X=pd.concat([d[[x]],pd.get_dummies(d.farm,drop_first=True,dtype=float)],axis=1); X=sm.add_constant(X); m=sm.OLS(d.yield_kg,X).fit()
 print(x,round(m.params[x],4),round(m.pvalues[x],6),round(m.rsquared,3))"}
